mapper.select:
SELECT COALESCE(SUM(quantity), 0)
FROM xsy_trace_unit
WHERE lot_id = #{lotId}

SELECT COALESCE(SUM(quantity), 0)
FROM xsy_inventory_lot_balance
WHERE lot_id = #{lotId}

SELECT u.id, u.unit_code AS unitCode, u.public_token AS publicToken, u.lot_id AS lotId, t.lot_no AS lotNo, t.source_lot_no AS sourceLotNo, u.package_type AS packageType, u.quantity, u.unit, u.net_weight AS netWeight, u.weight_unit AS weightUnit, u.weight_source AS weightSource, u.measured_at AS measuredAt, u.status, u.remark, u.created_at AS createdAt, u.created_by AS createdBy FROM xsy_trace_unit u LEFT JOIN xsy_trace_lot t ON t.id = u.lot_id WHERE 1 = 1 AND u.lot_id = #{query.lotId}
AND u.unit_code ILIKE CONCAT('%', #{query.unitCode}, '%')
AND t.lot_no ILIKE CONCAT( '%', #{query.lotNo}, '%') AND u.status = #{query.status}
AND FALSE
AND EXISTS (SELECT 1 FROM xsy_purchase_receipt_item_lot rl JOIN xsy_purchase_receipt_item ri ON ri.id = rl.purchase_receipt_item_id JOIN xsy_purchase_receipt r ON r.id = ri.purchase_receipt_id WHERE rl.lot_id = u.lot_id AND r.deleted = FALSE AND r.warehouse_id IN #{scopeId} )
ORDER BY u.id DESC

mapper.update:
UPDATE xsy_trace_unit
SET net_weight = #{netWeight}, weight_unit = #{weightUnit}, weight_source = #{weightSource},
    measured_at = #{measuredAt}
WHERE id = #{id}
    AND net_weight IS NULL
